// Pre-requisite: iopl(3) or ioperm(port, len, 1) must be called

#define ATA_DATA_PORT 0x1F0
#define SECTOR_WORDS 256  // 512 bytes / 2 bytes per word

uint16_t data_buffer[SECTOR_WORDS];
unsigned short port = ATA_DATA_PORT;
void *addr = data_buffer;
unsigned long count = SECTOR_WORDS;

// Perform 256 word inputs from the port to the buffer
// Buffer size must be at least count * 2 bytes
insw(port, addr, count);
